const html = items[0].json;

// Extract all JSON-LD blocks
const scriptRegex = /<script[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/gi;

let match;
let software = null;

while ((match = scriptRegex.exec(html)) !== null) {
  try {
    const json = JSON.parse(match[1]);

    if (json["@type"] === "SoftwareApplication" && Array.isArray(json.review)) {
      software = json;
      break;
    }
  } catch (e) {}
}

if (!software) {
  return [{
    json: {
      error: "SoftwareApplication JSON-LD not found."
    }
  }];
}

const reviews = software.review.map(r => ({
  reviewer: r.author?.name || "",
  title: r.name || "",
  rating: Number(r.reviewRating?.ratingValue || 0),
  review: (r.reviewBody || "")
    .replace(/<[^>]+>/g, "")
    .replace(/\s+/g, " ")
    .trim(),
  date: r.datePublished || ""
}));

const averageRating =
  reviews.length
    ? reviews.reduce((sum, r) => sum + r.rating, 0) / reviews.length
    : 0;

return [{
  json: {
    company: software.name,
    totalReviews: reviews.length,
    averageRating: Number(averageRating.toFixed(2)),
    reviews
  }
}];

const reviews = $json.reviews || [];

const today = new Date();
const sevenDaysAgo = new Date(today);
sevenDaysAgo.setDate(today.getDate() - 7);

const recentReviews = reviews.filter(review => {
  const reviewDate = new Date(review.date);
  return reviewDate >= sevenDaysAgo && reviewDate <= today;
});

const averageRating = recentReviews.length
  ? recentReviews.reduce((sum, r) => sum + r.rating, 0) / recentReviews.length
  : 0;

return [{
  json: {
    company: $json.company,
    reviewCount: recentReviews.length,
    averageRating: Number(averageRating.toFixed(2)),
    reviews: recentReviews
  }
}];
